/// The fields of an `EntryV1`, to write
public struct EntryV1Fields: Hashable, Sendable {
    /// The alignment that a parent pads an `EntryV1` to: the largest alignment of its arrays
    /// and nested tables, or 1
    public static let alignment: Alignment = .one

    public var key: UInt16
    public var note: String?

    public init(key: UInt16, note: String? = nil) {
        self.key = key
        self.note = note
    }

    /// Adds an `EntryV1` to its parent's sizer, after the field or vector that holds it
    public func add(to sizer: inout TableSizer) {
        let parent = sizer.startTable(fields: 2)
        sizer.addUInt16()
        if let value = self.note {
            sizer.addString(value)
        }
        sizer.endTable(parent)
    }

    /// Writes an `EntryV1` where its parent's writer is, after the field or vector that holds it
    public func write(to writer: inout TableWriter) {
        let parent = writer.startTable(fields: 2)
        writer.setUInt16(0, self.key)
        if let value = self.note {
            writer.setString(1, value)
        } else {
            writer.setAbsent(1)
        }
        writer.endTable(parent)
    }
}

