@frozen
public struct Extent: Hashable, Sendable {
    /// The byte length of an `Extent`
    public static let size = 8
    /// The alignment of an array of `Extent`s: its largest scalar's size
    public static let alignment: Alignment = .four

    public var width: Float
    public var height: Float

    public init(width: Float, height: Float) {
        self.width = width
        self.height = height
    }

    /// Reads an `Extent` from the start of `bytes`.
    ///
    /// Throws a `DecodeError` if `bytes` are shorter than `size`.
    @inlinable
    public init(_ bytes: RawSpan) throws(DecodeError) {
        self.init(try TableReader(bytes).struct(at: 0, size: Self.size), at: 0)
    }

    /// Reads an `Extent` at `offset` in `bytes`, which hold its scalars there
    @inlinable
    init(_ bytes: RawSpan, at offset: Int) {
        self.width = Float(littleEndianBytes: bytes, at: offset)
        self.height = Float(littleEndianBytes: bytes, at: offset + 4)
    }

    /// The bytes of an `Extent`: its scalars, little-endian, one after another
    public func serialize() -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(Self.size)
        self.append(to: &bytes)
        return bytes
    }

    /// The bytes of an array of `Extent`s, as a table holds them: theirs, one after another
    public static func serializeArray(_ items: [Self]) -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(items.count * Self.size)
        for item in items {
            item.append(to: &bytes)
        }
        return bytes
    }

    /// Appends the scalars to `bytes`, little-endian
    func append(to bytes: inout [UInt8]) {
        withUnsafeBytes(of: self.width.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
        withUnsafeBytes(of: self.height.bitPattern.littleEndian) { bytes.append(contentsOf: $0) }
    }

    /// Writes the scalars where `writer` is, little-endian, after the `setStruct(_:)` or the
    /// `setStructArray(_:count:alignment:)` of the field that holds them
    public func write(to writer: inout TableWriter) {
        writer.writeScalar(self.width)
        writer.writeScalar(self.height)
    }
}

/// A message without a version, whose second revision appends `count`
@frozen
public struct Sample: ~Escapable {
    /// The layout that a `Sample` is written and read in
    @inlinable
    public static var layout: TableLayout { TableLayout.default }

    @usableFromInline
    let _reader: TableReader

    /// Reads a `Sample` from `bytes`, which it can't outlive
    @inlinable
    @_lifetime(copy bytes)
    public init(_ bytes: RawSpan) {
        _reader = TableReader(bytes, layout: Self.layout)
    }

    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var key: UInt32 {
        get throws(DecodeError) { try _reader.uint32(at: _reader.rootOffset(0)) }
    }

    /// `7` when the table doesn't hold it, as `hasCount` tells.
    ///
    /// Throws a `DecodeError` if the field lies outside the bytes.
    @inlinable
    public var count: UInt16 {
        get throws(DecodeError) {
            guard try _reader.rootOffset(0) >= 8 else {
                return 7
            }

            let field = try _reader.rootOffset(1)
            guard field != 0 else {
                return 7
            }

            return try _reader.uint16(at: field)
        }
    }

    /// Whether the table holds `count`.
    ///
    /// Throws a `DecodeError` if an offset that it reads lies outside the bytes.
    @inlinable
    public var hasCount: Bool {
        get throws(DecodeError) {
            guard try _reader.rootOffset(0) >= 8 else {
                return false
            }

            return try _reader.rootOffset(1) != 0
        }
    }
}

/// The fields of a `Sample`, to write
public struct SampleFields: Hashable, Sendable {
    public var key: UInt32
    public var count: UInt16

    public init(key: UInt32, count: UInt16) {
        self.key = key
        self.count = count
    }

    /// Writes a `Sample` with every field.
    ///
    /// Throws a `BuildError` if it's longer than its offset type, `uint32`, addresses.
    public func serialize() throws(BuildError) -> [UInt8] {
        var sizer = try TableSizer(fields: 2, layout: Sample.layout)
        sizer.addUInt32()
        sizer.addUInt16()

        return try sizer.bytes { writer in
            writer.setUInt32(0, self.key)
            writer.setUInt16(1, self.count)
        }
    }
}

